// A simplified First Fit search over a free list of holes
// holes is a linked list of free blocks ordered by memory address
struct FreeBlock {
    int size;
    struct FreeBlock* next;
};

struct FreeBlock* firstFit(struct FreeBlock* holes, int requestSize) {
    struct FreeBlock* current = holes;
    while (current != NULL) {
        if (current->size >= requestSize) {
            return current; // first hole large enough wins, whatever remains stays behind
        }
        current = current->next;
    }
    return NULL; // no single contiguous hole was large enough
}

